import{_ as o,l,o as e,c as n,v as t,p as s,x as r,d,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"符号执行 KLEE","description":"","frontmatter":{"title":"符号执行 KLEE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/symbolic-execution.md","filePath":"cs/symbolic-execution.md","lastUpdated":1789023840000}'),h={name:"cs/symbolic-execution.md"};function p(u,a,m,_,f,b){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="符号执行-klee" tabindex="-1">符号执行 KLEE <a class="header-anchor" href="#符号执行-klee" aria-label="Permalink to &quot;符号执行 KLEE&quot;">​</a></h1><div class="epigraph"><p>把输入当成符号，路径谓词交给 SMT，求解器吐出能走这条路径的具体字节。KLEE 在 LLVM 上这样找崩溃与断言失败；路径爆炸是它的税。</p><footer>—— Cadar, Dunbar and Engler, KLEE, OSDI 2008；King, Symbolic Execution, 1976</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/coverage-guided-fuzzing">fuzz</a>随机走。缺口是<strong>精确满足分支条件</strong>。主干<a href="/cs/smt-solver">SMT</a>已有求解器。本课把符号执行接到测试生成，不重推 SMT。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>fuzz 难猜 magic number。符号执行：每条分支加约束，<code>unsat</code> 则剪。缺口是循环与状态空间；混合（concolic）用具体跑加符号补。环境建模（系统调用）是工程。</p><h3 id="不是证明无洞" tabindex="-1">不是证明无洞 <a class="header-anchor" href="#不是证明无洞" aria-label="Permalink to &quot;不是证明无洞&quot;">​</a></h3><p>没扫到的路径沉默。与 fuzz、审计互补。</p><p><span class="marginnote">King 1976；KLEE OSDI 2008。本课不把求解器当攻击工具教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照具体执行与符号状态。指出与覆盖 fuzz 混合：求解器解卡住的比较。下一课静态污点：不跑程序也追踪数据流。</p>',12)),(e(),s(E,null,{default:r(()=>[c(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%5B%22%E7%AC%A6%E5%8F%B7%E8%BE%93%E5%85%A5%22%5D%20--%3E%20BR%5B%22%E5%88%86%E6%94%AF%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20BR%20--%3E%20SMT%5B%22SMT%22%5D%0A%20%20SMT%20--%3E%20IN%5B%22%E5%85%B7%E4%BD%93%E8%BE%93%E5%85%A5%22%5D%0A%20%20IN%20--%3E%20TEST%5B%22%E5%9B%9E%E5%BD%92%E7%94%A8%E4%BE%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>发现手段在「动态随机 / 动态符号 / 静态」之间权衡。下一课静态与污点分析。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写破解某二进制保护的符号执行菜谱。静态污点下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>fuzz 不擅长 magic；符号执行解路径条件。</li><li>KLEE 在 LLVM 上生成测试。</li><li>路径爆炸与环境是边界。</li><li>下一课静态与污点。</li><li>出处：Cadar, Dunbar and Engler, OSDI 2008；King, 1976。</li></ul>',8))])}const B=o(h,[["render",p]]);export{S as __pageData,B as default};
